import{_ as o,o as d,c,ae as a}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"El modelo de datos de red","description":"","frontmatter":{},"headers":[],"relativePath":"es/reference/04-modelo-de-datos-de-red.md","filePath":"es/reference/04-modelo-de-datos-de-red.md"}'),t={name:"es/reference/04-modelo-de-datos-de-red.md"};function s(r,e,n,l,i,p){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="el-modelo-de-datos-de-red" tabindex="-1">El modelo de datos de red <a class="header-anchor" href="#el-modelo-de-datos-de-red" aria-label="Permalink to &quot;El modelo de datos de red&quot;">​</a></h1><p><code>class Network</code> (<code>network.js:101</code>), una única instancia <code>window.Net</code>. Es el store canónico de todo lo que el usuario construye.</p><h2 id="formas-de-los-elementos" tabindex="-1">Formas de los elementos <a class="header-anchor" href="#formas-de-los-elementos" aria-label="Permalink to &quot;Formas de los elementos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Colección</th><th>Forma</th></tr></thead><tbody><tr><td><code>nodes[]</code></td><td><code>{ id, type, lngLat:[lng,lat], props }</code></td></tr><tr><td><code>links[]</code></td><td><code>{ id, type, from, to, vertices[], props }</code> (<code>vertices</code> = coordenadas intermedias)</td></tr><tr><td><code>subcatchments[]</code></td><td><code>{ id, ring:[[lng,lat]…], props }</code></td></tr><tr><td><code>mesh2D[]</code></td><td><code>{ id:&#39;M2D_n&#39;, ring, manningN, parentSubcatch, props }</code> — derivado de la malla indexada</td></tr><tr><td><code>mesh2DIndexed</code></td><td>Salida del motor Triangle; ver el modelo de datos de la malla 2D</td></tr><tr><td><code>timeseries</code></td><td><code>{ TS1: [{date,time,value}…] }</code></td></tr><tr><td><code>options</code>, <code>units</code></td><td>Opciones de simulación, <code>&#39;SI&#39;</code>/<code>&#39;US&#39;</code></td></tr><tr><td>Metadata</td><td><code>title</code>, <code>counters</code>, <code>rawSections</code>, <code>curves</code>, <code>lidControls</code>, <code>pollutants</code>, <code>landUses</code>, <code>treatments</code>, <code>aquifers</code>, <code>snowpacks</code>, <code>importedLayers</code></td></tr></tbody></table><h2 id="propiedades-por-defecto" tabindex="-1">Propiedades por defecto <a class="header-anchor" href="#propiedades-por-defecto" aria-label="Permalink to &quot;Propiedades por defecto&quot;">​</a></h2><p>Las <strong>props por defecto</strong> vienen de factories: <code>defaultNodeProps(type)</code>, <code>defaultLinkProps(type)</code>, <code>defaultSubcatchProps()</code> (<code>network.js:30-54</code>). Por ejemplo, JUNCTION <code>{invertEl, maxDepth:2, initDepth, surDepth, aponded}</code>; CONDUIT <code>{roughness:0.013, autoLength:true, xShape:&#39;CIRCULAR&#39;, geom1:1.0, barrels:1}</code>.</p><h2 id="ids-indices-cache-geojson" tabindex="-1">IDs, índices, caché GeoJSON <a class="header-anchor" href="#ids-indices-cache-geojson" aria-label="Permalink to &quot;IDs, índices, caché GeoJSON&quot;">​</a></h2><ul><li><strong>Generación de IDs</strong> (<code>nextId</code>, <code>network.js:171-181</code>): contadores por tipo con prefijos de <code>ID_PREFIX</code> (<code>network.js:19-23</code>): nodos <code>J/O/ST/D/RG</code>, enlaces <code>C/P/W/OR/OL</code>, subcuencas <code>S</code>, celdas de malla <code>M2D_</code>.</li><li><strong>Búsqueda O(1):</strong> <code>_nodeMap/_linkMap/_subMap</code> reconstruidos por <code>rebuildIndexes()</code> (<code>network.js:141-150</code>); <code>findAny(id)</code> (<code>network.js:197-212</code>) también resuelve celdas de malla.</li><li><strong>Cachés GeoJSON:</strong> <code>nodesGeoJSON/linksGeoJSON/subcatchmentsGeoJSON/mesh2DGeoJSON</code> (<code>network.js:784-865</code>) invalidadas por <code>_invalidateGeo()</code>; los movimientos de nodo se parchean in place (<code>_patchGeoForMove</code>, <code>network.js:350-365</code>) para que los drags no reconstruyan todo.</li></ul><h2 id="undo-redo-patron-de-comandos" tabindex="-1">Undo/redo (patrón de comandos) <a class="header-anchor" href="#undo-redo-patron-de-comandos" aria-label="Permalink to &quot;Undo/redo (patrón de comandos)&quot;">​</a></h2><ul><li>El historial es un arreglo de snapshots completos <code>{t:&#39;snap&#39;, json}</code> y deltas <code>{t:&#39;cmd&#39;, op}</code>. <code>HISTORY_LIMIT=100</code>, con snapshots forzados cada 25 ops (<code>network.js:25-26</code>).</li><li><code>_record(op)</code> (<code>network.js:534-544</code>) registra deltas; <code>commit()</code> (<code>network.js:524-532</code>) empuja un snapshot (usado después de ops masivas como clear/merge).</li><li>Tipos de op (<code>_applyOp</code>, <code>network.js:636-674</code>): <code>add</code>, <code>del</code> (en cascada a los enlaces conectados, restaura refs de outlet/gage), <code>move</code>, <code>props</code>, <code>rename</code>, <code>units</code>.</li><li><code>undo/redo</code> (<code>network.js:565-586</code>); <code>_trimHistory</code> (<code>network.js:546-560</code>) elimina las entradas más antiguas; <code>canUndo/canRedo</code> manejan los estados de los botones de la toolbar.</li></ul><h2 id="mutaciones" tabindex="-1">Mutaciones <a class="header-anchor" href="#mutaciones" aria-label="Permalink to &quot;Mutaciones&quot;">​</a></h2><p><code>addNode</code> (<code>226-240</code>), <code>addLink</code> (<code>242-258</code>, auto-computa el largo del conducto), <code>addSubcatchment</code> (<code>260-284</code>, auto-computa el área en ha/ac y elige el nodo hidráulico más cercano como outlet), <code>moveNode/commitMove</code> (<code>318-336</code>), <code>updateProps</code> (<code>367-382</code>), <code>renameElement</code> (<code>384-393</code>), <code>deleteElements</code> (<code>414-451</code>), <code>setUnits</code> (<code>453-462</code>). Cada mutación emite <code>Net.emit()</code> → los suscriptores de <code>Net.onChange</code> re-renderizan (<code>app.js:632-640</code>).</p><h2 id="serializacion" tabindex="-1">Serialización <a class="header-anchor" href="#serializacion" aria-label="Permalink to &quot;Serialización&quot;">​</a></h2><p><code>serialize()</code> (<code>network.js:465-488</code>) es el volcado canónico del modelo (versión 2); <code>loadState()</code> (<code>network.js:490-520</code>) lo restaura, reconstruyendo índices y la malla indexada. <code>rawSections</code> (texto INP verbatim de las importaciones) se preserva para que los datos que la UI no tiene editor sobrevivan los round-trips.</p>',14)])])}const h=o(t,[["render",s]]);export{u as __pageData,h as default};
